<script lang="ts">
 import V2PageLayout from '../components/V2PageLayout.svelte'; import V2Tabs from '../components/V2Tabs.svelte'; import V2Zone from '../components/V2Zone.svelte'; import V2ZoneLabel from '../components/V2ZoneLabel.svelte'; import V2Section from '../components/V2Section.svelte'; import V2Card from '../components/V2Card.svelte'; import V2Stack from '../components/V2Stack.svelte'; import V2Inline from '../components/V2Inline.svelte'; import V2Badge from '../components/V2Badge.svelte'; import V2Field from '../components/V2Field.svelte';
 type Mode='Side by side'|'Swipe'|'Transparency'|'Difference';
 let tab=$state('Review'), compare=$state(false), group=$state(1), member=$state(0), reference=$state(0), mode=$state<Mode>('Side by side'), zoom=$state(100), split=$state(50), opacity=$state(50), panX=$state(0), panY=$state(0), diffHue=$state(190), diffContrast=$state(180), diffBinary=$state(true), dragging=$state(false), lastX=$state(0), lastY=$state(0), decisions=$state<Record<number,string>>({});
 const groups=[{id:1,count:2,state:'Actionable',tone:'ok',kind:'Exact pair'},{id:2,count:2,state:'Needs review',tone:'warn',kind:'Similar pair'},{id:3,count:3,state:'Actionable',tone:'ok',kind:'Exact group'},{id:4,count:5,state:'Needs decisions',tone:'warn',kind:'Mixed group'},{id:5,count:6,state:'Actionable',tone:'ok',kind:'Similarity cluster'},{id:6,count:9,state:'Blocked',tone:'bad',kind:'Large cluster'},{id:7,count:10,state:'Needs review',tone:'warn',kind:'Large similarity cluster'}] as const;
 const activeCount=$derived(groups.find(g=>g.id===group)?.count??2), transform=$derived(`translate(${panX}px,${panY}px) scale(${zoom/100})`);
 function openCompare(g:number,i:number){group=g;member=i;reference=0;decisions={};compare=true;fit()}; function fit(){zoom=100;panX=0;panY=0}; function actual(){zoom=120;panX=0;panY=0}; function prev(){member=(member-1+activeCount)%activeCount}; function next(){member=(member+1)%activeCount}; function pointerDown(e:PointerEvent){if((e.target as HTMLElement).closest('button,input,select'))return;dragging=true;lastX=e.clientX;lastY=e.clientY;(e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId)} function pointerMove(e:PointerEvent){if(!dragging)return;panX+=e.clientX-lastX;panY+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY} function wheel(e:WheelEvent){e.preventDefault();zoom=Math.max(10,Math.min(800,zoom*(e.deltaY<0?1.12:1/1.12)))}
</script>
<svelte:window onkeydown={(e)=>{if(e.key==='Escape'&&compare)compare=false}} onpointerup={()=>dragging=false}/>
<V2PageLayout title="Duplicates" description="Review exact and similarity duplicate groups, save member decisions, and process only actionable groups.">{#snippet headerActions()}<V2Inline gap="sm"><button class="v2-button">Scan similar</button><button class="v2-button v2-button-primary">Review actions</button></V2Inline>{/snippet}{#snippet tabs()}<V2Tabs items={['Review','Rules & discovery','Resolution history']} active={tab} onselect={(v)=>tab=v}/>{/snippet}{#snippet context()}<V2Zone label="Context rail"><V2Section title="Review filter"><V2Stack gap="sm"><select><option>All groups</option><option>Needs review</option><option>Auto-ready</option><option>Blocked</option></select><button class="v2-button">Select auto-ready</button></V2Stack></V2Section><V2Section title="Similarity"><V2Field label="Threshold" value="82"/><V2Inline gap="sm"><button class="v2-button">Scan again</button><button class="v2-button">Cancel scan</button></V2Inline><span class="v2-small v2-muted">Similarity is review evidence only.</span></V2Section><V2Section title="Bulk preset"><V2Stack gap="sm"><button class="v2-button">Keep all copies</button><button class="v2-button">Mark all for deletion</button><button class="v2-button">Stack each group</button></V2Stack></V2Section></V2Zone>{/snippet}<V2Zone><V2Inline justify="between" wrap={true}><V2Inline gap="sm" wrap={true}><V2ZoneLabel text="Primary content"/><V2Badge text="18 groups"/><V2Badge tone="ok" text="7 ready"/><V2Badge tone="warn" text="3 blocked"/></V2Inline><button class="v2-button">Clear decisions</button></V2Inline>{#each groups as g}<V2Card class="v2-duplicate-group"><V2Stack gap="md"><V2Inline justify="between" align="start" wrap={true}><V2Inline gap="sm" wrap={true}><input type="checkbox"><b>Group {g.id}</b><V2Badge text={`${g.count} images`}/><V2Badge text={g.kind}/><V2Badge tone={g.tone} text={g.state}/></V2Inline><V2Inline gap="sm"><button class="v2-button">Apply preset</button><button class="v2-button" onclick={()=>openCompare(g.id,0)}>Compare</button></V2Inline></V2Inline><div class="v2-duplicate-members">{#each Array.from({length:g.count},(_,i)=>i) as i}<div class="v2-duplicate-member"><button class="v2-duplicate-image" onclick={()=>openCompare(g.id,i)}><span>Member {i+1}</span><small>{i===0?'Suggested keeper':i%3===0?'External':'Immich'}</small></button><div class="v2-duplicate-actions"><button class={`v2-button ${i===0?'v2-button-primary':''}`}>Keep</button><button class="v2-button">Delete</button><button class="v2-button">Stack</button></div></div>{/each}</div></V2Stack></V2Card>{/each}</V2Zone>{#snippet inspector()}<V2Zone label="Inspector"><V2Section title="Batch readiness"><V2Card><V2Stack gap="sm"><b>2 selected groups</b><span class="v2-small v2-muted">All selected groups must pass actionability guards before execution.</span><V2Inline gap="sm"><V2Badge tone="ok" text="2 ready"/><V2Badge text="0 blocked"/></V2Inline></V2Stack></V2Card></V2Section><V2Section title="Current group"><V2Card><span class="v2-small">Keeper: Member 1<br>Delete: 1<br>Stack: 0<br>Online: all</span></V2Card></V2Section></V2Zone>{/snippet}</V2PageLayout>
{#if compare}<div class="v2-compare-viewer" role="dialog" aria-modal="true"><div class="v2-compare-top"><V2Inline gap="sm"><button class="v2-button" onclick={()=>compare=false}>✕</button><b>Duplicate comparison</b><V2Badge text={`Group ${group}`}/><V2Badge text={`${activeCount} images`}/></V2Inline><V2Inline gap="sm" wrap={true}><div class="v2-segmented">{#each ['Side by side','Swipe','Transparency','Difference'] as m}<button class:active={mode===m} onclick={()=>{mode=m as Mode;fit()}}>{m}</button>{/each}</div><button class="v2-button" onclick={()=>zoom=Math.max(10,zoom/1.12)}>−</button><span class="v2-small v2-muted">{Math.round(zoom)}%</span><button class="v2-button" onclick={()=>zoom=Math.min(800,zoom*1.12)}>+</button><button class="v2-button" onclick={fit}>Fit</button><button class="v2-button" onclick={actual}>1:1</button><button class="v2-button" onclick={prev}>← Previous</button><button class="v2-button" onclick={next}>Next →</button><button class="v2-button" onclick={()=>reference=member}>Set as reference</button><button class="v2-button" onclick={()=>window.alert('Mock integrity analysis: current asset is healthy.')}>Analyze integrity</button></V2Inline></div><div class="v2-compare-main"><section class="v2-compare-visual"><div class="v2-compare-stage" class:single={mode!=='Side by side'} onpointerdown={pointerDown} onpointermove={pointerMove} onwheel={wheel}>{#if mode==='Side by side'}<div class="v2-compare-pane"><span class="v2-compare-label">Selected image</span><div class="v2-compare-image" style={`transform:${transform}`}></div></div><div class="v2-compare-pane"><span class="v2-compare-label">Reference / keeper candidate</span><div class="v2-compare-image alt" style={`transform:${transform}`}></div></div>{:else}<div class={`v2-compare-overlay mode-${mode.toLowerCase().replaceAll(' ','-')}`}><div class="v2-compare-layer base" style={`transform:${transform}`}></div><div class="v2-compare-layer top" style={`${mode==='Transparency'?`opacity:${opacity/100};`:mode==='Swipe'?`clip-path:inset(0 ${100-split}% 0 0);`:''}transform:${transform}`}></div>{#if mode==='Swipe'}<div class="v2-compare-hover"><span>Split</span><input type="range" min="0" max="100" bind:value={split}><b>{split}%</b></div>{/if}{#if mode==='Transparency'}<div class="v2-compare-hover"><span>Transparency</span><input type="range" min="0" max="100" bind:value={opacity}><b>{opacity}%</b></div>{/if}{#if mode==='Difference'}<div class="v2-difference-mask" style={`--diff-hue:${diffHue};--diff-contrast:${diffContrast}%`}><span>Difference preview</span></div><div class="v2-difference-controls"><label><span>Color</span><input type="range" min="0" max="360" bind:value={diffHue}><b>{diffHue}°</b></label><label class="v2-check-row"><input type="checkbox" bind:checked={diffBinary}>Two colors only</label>{#if !diffBinary}<label><span>Contrast</span><input type="range" min="50" max="300" bind:value={diffContrast}><b>{diffContrast}%</b></label>{/if}</div>{/if}<div class="v2-compare-legend"><span>Reference {reference+1}</span><span>Selected {member+1}</span></div></div>{/if}</div><div class="v2-filmstrip">{#each Array.from({length:activeCount},(_,i)=>i) as i}<button class="v2-thumb" class:active={i===member} class:reference={i===reference} onclick={()=>member=i}>Member {i+1}</button>{/each}</div></section><aside class="v2-compare-data"><V2Section title="Quick comparison"><V2Card><V2Stack gap="sm"><V2Inline justify="between"><span>Visual similarity</span><b>{(99.4-(member*.65)%8).toFixed(1)}%</b></V2Inline><V2Inline justify="between"><span>File size difference</span><b>+0.6 MB</b></V2Inline><V2Inline justify="between"><span>Resolution</span><b>Same</b></V2Inline><V2Inline justify="between"><span>Integrity</span><V2Badge tone="ok" text="Healthy"/></V2Inline></V2Stack></V2Card></V2Section><V2Section title="Metadata side by side"><div class="v2-compare-grid"><b>Selected</b><b>Reference</b><span>IMG_000{member+1}.jpg</span><span>IMG_000{reference+1}.jpg</span><span>{member%2?'External library':'Immich upload'}</span><span>{reference%2?'External library':'Immich upload'}</span><span class="changed">5.4 MB</span><span class="changed">4.8 MB</span><span>4032 × 3024</span><span>4032 × 3024</span></div></V2Section><V2Section title="Decision context"><V2Card><b>Highlighted cells differ.</b><p class="v2-small v2-muted">Use image evidence and metadata together. Similarity alone does not authorize deletion.</p></V2Card></V2Section></aside></div><div class="v2-compare-actions"><span><b>Member {member+1}</b> <span class="v2-small v2-muted">Choose disposition for this member</span></span><V2Inline gap="sm">{#each ['keep','delete','stack'] as decision}<button class={`v2-button ${decisions[member]===decision?'v2-button-primary':''}`} onclick={()=>decisions={...decisions,[member]:decision}}>{decision[0].toUpperCase()+decision.slice(1)}</button>{/each}<button class="v2-button" disabled={decisions[member]!=='stack'} onclick={()=>window.alert(`Member ${member+1} set as stack primary in this mockup.`)}>Set stack primary</button></V2Inline></div></div>{/if}
